update content_bodies set title = 'ART&FACTORY JAPAN トレーラー', description = 'ウェブサイト
https://etooto.jp/

第3回日本国際観光映像祭は世界の映像クリエイターたちと観光映像のあり方を模索するために、ART&FACTORY JAPANを開催いたします。

日本の世界観光映像祭が「ART&FACTORY JAPAN」を開催します。この目的は、世界中のクリエイターとのコンテストを通じて、観光映像とデジタルマーケティングの未来の可能性を探ることです。（YouTubeタブで字幕を見ることができます。）

これはポルトガルの観光映像祭、ART&TURが始めた新しい形のコンテストであり、世界各国のクリエイターたちを観光地に招待し、その地域の課題解決のために、短期間で映像を制作する企画です。

今年はCOVID-19の拡大を踏まえて、日本からのクリエイターを招待します。開催地は鹿児島県与論町です。

作家たちは2021年2月に3泊4日で与論島に滞在し、それぞれの力量を発揮した観光映像を制作します。そして京都の清水寺で開催される第3回日本国際観光映像祭でプレミア上映し、コンテストを行います。

詳細は日本国際観光映像祭のホームページでご確認ください。
https://jwtff.world

