Japan World''s Tourism Film Festival will open, "ART&FACTORY JAPAN." This aim is to explore the possibility of future in Tourism Film and digital marketing by means of contest with creators from all over the world. 

Japan World''s Tourism Film Festival will open, "ART&FACTORY JAPAN." This aim is to explore the possibility of future in Tourism Film and digital marketing by means of contest with creators from all over the world.

This is a new type of contest initiated by ART&TUR, the Portuguese tourism film festival, which invites creators from all over the world to a tourist destination to create a short film to solve a problem in that area.

This year, based on the expansion of COVID-19, creators from Japan will be invited. The event will be held in Yoron town, Kagoshima prefecture.

The artists will stay on Yoron Island for 4 days and 3 nights in February 2021 and produce a tourism film that demonstrates their respective abilities. The films will then be premiered at the 3rd Japan International Tourism Film Festival at Kiyomizu Temple in Kyoto, where a competition will be held.

For more information, please visit the Japan World''s Tourism Film Festival website.
https://jwtff.world' where id = 'EKbEnSxakkTD4vLFOeQtI';
update content_bodies set title = 'THE ROOTS #05 人に伝えたくなるメロン', description = 'WEB SITE
https://etooto.jp/

瀬戸内海の穏やかな島
因島重井町は、スイカの名産地。
ただ、ごく少数の農家さんによって
極上のマスクメロンが栽培されることを
知る人は多くない。

その稀少な「因島メロン」を
稼業として継ぎ
「熊八屋」を盛り立てる
村上智規（むらかみとものり）さん。
瀬戸の凪をうわまわる穏やかさ、
元・絵描きらしい。

「熊八屋」とは
智規さんが彼女とメロンに惚れ込んで
婿入りした農家の屋号で、
初代“熊八じいさん”に由来する。
（重井町にはユニークな屋号が多く残る）
智規さんは五代目。

「甘さ」は糖度計で測れるけど、
「美味しさ」とは、人の心が動くこと。
つくり手の想いを
島の子どもたちにも届ける。
給食にメロンだ。贅沢っ！

適期適作。
メロンも、子どもたちも
おおらかな島の時間に添うて、
愛され、育つ。
美味しさの理由はそこにある。

さあ、ひとくち、召し上がれ。' where id = 'JnlzkuoHId5TfS5DyHe4F';
update content_bodies set title = 'THE ROOTS #05 A Melon You Want to Share with Others', description = 'WEB SITE
https://etooto.jp/

A tranquil island in the Seto Inland Sea,
Inushima Shigei Town is famous for its watermelons.
However, not many people know that
only a handful of farmers cultivate
exquisite musk melons.

Tomonori Murakami, who continues the rare
"Inushima Melon" as a family business
and supports "Kumahachiya."
He embodies the calmness that surpasses
the tranquility of the Seto Sea,
a former painter.

"Kumahachiya" is the name of the farm
where Tomonori fell in love with his girlfriend
and melons, and it is derived from
the first generation "Kumahachi-san."
(Shigei Town has many unique farm names.)
Tomonori is the fifth generation.

While "sweetness" can be measured with a sugar meter,
"deliciousness" is about moving people''s hearts.
He delivers the feelings of the producers
even to the children of the island.
Melon in school lunches. How luxurious!

Timely and appropriate cultivation.
Both melons and children
grow loved and nurtured,
along with the generous time of the island.
The reason for their deliciousness lies there.

Now, take a bite and enjoy.' where id = '_JShQ5TmLaBHoNH3iSHzq';
update content_bodies set title = 'THE ROOTS #02 一年で嫁ぐにんにく', description = 'WEB SITE
https://etooto.jp/

福山市加茂町で農業を営む
岡本啓二（おかもとけいじ）さん。
20年前から農業に たずさわり、
にんにくを作り始めたのは3年前。

無農薬＝除草剤を使わないこと。
すると、畑の畔には雑草が生い茂るし
虫だって集まってくる。
当然、手間はかかるし、心配も絶えない。

それでも、手がかかる「娘」ほどかわいい。

溢れんばかりの愛情をたっぷり受けて
天真爛漫に育った「娘」たちは
雑味がなく、素直な味がする。
それは、ほかの野菜も同じこと。

素直な素材には、シンプルな調理を。
岡本さんオススメの食べ方は、
にんにくを塩こしょうだけで炒めること。

まずはひとかけ、めしあがれ。' where id = '0mPF_e6n3DtR7AJoM9RzM';
update content_bodies set title = 'THE ROOTS #02 Garlic Married in a Year', description = 'WEB SITE
https://etooto.jp/

Keiji Okamoto, who runs a farm in Kamo Town, Fukuyama.
He has been involved in agriculture for 20 years,
and started growing garlic three years ago.

No pesticides = not using herbicides.
As a result, weeds grow thick along the field''s edge,
and insects gather as well.
Naturally, it takes effort, and worries never cease.

Even so, the ''daughter'' that requires care is the most precious.

Receiving an abundance of overflowing love,
the ''daughters'' have grown up carefree,
with a pure and straightforward taste.
The same goes for other vegetables.

For simple ingredients, simple cooking.
Mr. Okamoto''s recommended way to enjoy it is
to sauté garlic with just salt and pepper.

First, try one clove.' where id = 'Ujr_hq5ufjfPSvi46HQm2';
