update content_bodies set title = '[09_Unique Venue ユニークベニュー] Technical Visit & Unique Venue –Journey to Nagoya-', description = 'This is a promotional video created by the Aichi-Nagoya MICE Promotion Council, featuring unique venues that represent the history, culture and technology of the region.
