update content_bodies set title = '丹波山観光PR 武田家の隠し金山探検', description = '武田信玄の時代、黒川金山採掘のため、丹波山村に金山奉行が置かれていたと伝えられています。村内には、その跡が残っており、ガイドとともに金山跡を目指します。
