#ベスト北海道　#北海道観光　#もいわ山山頂展望台　#札幌で最も高い場所にあるクリスマスツリー

今回は、日本新三大夜景に認定されている札幌の絶景夜景スポット「もいわ山山頂展望台」を紹介します。

札幌市のほぼ中央に位置する標高531mの藻岩山。その山頂にある展望台からは昼夜問わず札幌の街を一望することができます。

恋人の聖地としても認定されるこの山頂展望台には「幸せの鐘」が設置されており、カップルにも人気のスポット。
12月25日までの間、「幸せの鐘」は”札幌で最も高い場所にあるクリスマスツリー”に装飾されており、夜はイルミネーションが煌めきます。

ぜひ美しい夜景とイルミネーションをご覧ください。

詳しくはこちらから！
https://mt-moiwa.jp/event/xmas2022/


This time, we will introduce the superb view spot "Mt. Moiwa Summit Observation Deck" a spectacular night view spot in Sapporo that has been certified as one of Japan''s New Three Great Night Views.

Mt. Moiwa with an altitude of 531m is located almost in the center of Sapporo city.
From Summit Observation Deck, you can overlook the city of Sapporo regardless of day or night.

The Summit Observation Deck, which is also certified as "Lover''s Sactuary", has a "Bell of Happiness" and is a popular spot for couples.
Until December 25th, the "Bell of Happiness" is decorated as "the tallest Christmas tree in Sapporo" and is illuminated at night.

Please take a look at the beautiful night view and illumination on site.

For more information is here！
https://mt-moiwa.jp/event/xmas2022/


