update content_bodies set title = 'CYCLING SHIMANAMI 2022（サイクリングしまなみ2022）｜Japan’s biggest cycle event!｜しまなみ海道｜しまなみジャパン', description = '2022年10月30日（日）に開催された『サイクリングしまなみ2022』の模様を通して、しまなみ海道・ゆめしま海道の美しい景観とサイクリングの魅力を感じていただける動画を作成しました。地域住民やこの地の文化との触れ合いなど、しまなみ海道を楽しむためのヒントも随所にちりばめられています。この動画をご覧になって、ぜひ一度この地を訪れてみてください。皆さまのお越しをお待ちしています！

しまなみジャパン‐しまなみジャパン公式動画チャンネル
https://www.youtube.com/channel/UCagGHddQzevo0QIl3ZUIo2A

しまなみジャパン - しまなみ体験ナビゲーション
https://shimanami-cycle.or.jp/


▼ English 　------------------------------------------

The 70km-long Shimanami Kaido in Japan is one of the world’s most beautiful and accessible bike routes, and is enjoyable at any time of the year. The CYCLING SHIMANAMI event, however, is a true festival of cycling. Around 7,000 riders come from all over Japan and around the world for the rare opportunity to ride the iconic route via the expressway, the awesome views, local hospitality and relaxed vibe.
In 2022, CYCLING SHIMANAMI returned after a 4 year hiatus and was held under clear blue skies, in bright sunshine – perfect conditions for island hopping by bike.
The islands look absolutely stunning and we hope that this short film will prompt you to start planning your own cycling adventure on the Shimanami Kaido and Yumeshima Kaido.
We are looking forward to welcoming you to Shimanami!


SHIMANAMI JAPAN Official Web Site 
https://shimanami-cycle.or.jp/go-shimanami/

SHIMANAMI JAPAN Official Facebook
https://www.facebook.com/visitshimanamijapan

SHIMANAMI JAPAN Official Instagram
https://www.instagram.com/visitshimanamijapan/

SHIMANAMI JAPAN Official YouTube Channel
https://www.youtube.com/channel/UCagGHddQzevo0QIl3ZUIo2A' where id = 'Doxu6kpIx_cNdBuEDpL1B';
update content_bodies set title = 'CYCLING SHIMANAMI 2022｜Japan’s biggest cycle event!｜Shimanami Kaido｜Shimanami Japan', description = 'We created a video that allows you to experience the beautiful scenery of the Shimanami Kaido and Yumeshima Kaido, as well as the charm of cycling, through the event ''CYCLING SHIMANAMI 2022'' held on October 30, 2022. The video is filled with hints on how to enjoy the Shimanami Kaido, including interactions with local residents and the culture of the area. We hope you watch this video and consider visiting this place at least once. We look forward to welcoming you!

Shimanami Japan - Official Video Channel
https://www.youtube.com/channel/UCagGHddQzevo0QIl3ZUIo2A

