update content_bodies set title = '池田高校全国観光甲子園２０２２グランプリ受賞修学旅行コース', description = '徳島県立池田高等学校の観光班が全国観光甲子園２０２２でグランプリを受賞した修学旅行コースをそらの郷とタイアップ！商品化いたしました。

#そらの郷　#池田高校　#そらの郷山里物語　#にし阿波　#四国　#徳島県　#三好市　#観光甲子園　#グランプリ受賞' where id = 'zvV54BXqrYWm4jTrvNmfC';
update content_bodies set title = 'Ikeda High School National Tourism Koshien 2022 Grand Prix Award Winning School Trip Course', description = 'The tourism team of Tokushima Prefectural Ikeda High School has collaborated with Sora no Sato to commercialize the school trip course that won the Grand Prix at the National Tourism Koshien 2022!' where id = 'tzhAbLMH4mQXKksk9062X';
update content_bodies set title = '民泊体験2', description = '四国、徳島県の西部「そらの郷」は、四国の中央に位置するにし阿波（美馬市、三好市、つるぎ町、東みよし町）エリアです。
そらの郷山里物語では、教育旅行民泊の推奨を行っています。
生徒たちは家族の一員として迎えられ、茶摘みやタマネギ、ジャガイモ、雑穀の収穫など、少量多品目自給的農業を協働します。
収穫した旬の野菜や山菜を使って田舎料理を共同調理、家族団らんの食事での心の交流、自然に触れる体験などを行います。

岩野家
https://nohaku.net/event/%E5%B2%A9%E9%87%8E%E5%AE%B6/

#そらの郷　#そらの郷山里物語　#農泊　#民泊　#教育旅行　#にし阿波　#徳島　#四国　#体験型教育旅行　#自然　#体験　#教育　#交流　#共同調理　#郷土食　#ラフティング　#大歩危　#祖谷　#観光　#日本一の田舎暮らし体験　#石切り　#サイクリング　#そば米雑炊　#岩野家' where id = 'ad5vx-k19J8kcZgoVnc_i';
update content_bodies set title = 'Minpaku Experience 2', description = 'Sora no Sato, located in the western part of Tokushima Prefecture in Shikoku, is in the Nishi-Awa area (Mima City, Miyoshi City, Tsurugi Town, Higashi-Miyoshi Town) at the center of Shikoku.
At Sora no Sato Yamasato Monogatari, we promote educational travel minpaku.
Students are welcomed as family members and collaborate in small-scale, diverse self-sufficient agriculture, such as tea picking, onion, potato, and grain harvesting.
Using the seasonal vegetables and wild plants harvested, we cook rural dishes together, share meals for heartfelt exchanges, and engage in experiences that connect with nature.

Iwano Family
https://nohaku.net/event/%E5%B2%A9%E9%87%8E%E5%AE%B6/

#Sora no Sato #Sora no Sato Yamasato Monogatari #Agricultural Stay #Minpaku #Educational Travel #Nishi-Awa #Tokushima #Shikoku #Experiential Educational Travel #Nature #Experience #Education #Exchange #Collaborative Cooking #Local Cuisine #Rafting #Oboke #Iya #Tourism #Japan''s Best Rural Living Experience #Stone Cutting #Cycling #Buckwheat Rice Porridge #Iwano Family' where id = 'tQJAHNH4QDW4vxFdKgD-z';
update content_bodies set title = 'そらの郷南紀州視察研修', description = 'そらの郷山里物語教育旅行受入家庭のスキルアップと
受入家庭同士の交流を図るため
南紀州へ視察研修に行ってきました。
自分たちが、生徒になって民泊家庭で体験、
どんなことをしたら喜んでもらえるか、
自分たちの町に帰って何ができるか、
やっぱり自分たちの町が一番良い！！などなど
色々考えるきっかけとなりました。
来年度春からの受入に向け、また、一致団結しました！！
目標を高く掲げ、こなしていくそらの郷山里物語、
教育旅行受入一緒にしてみませんか？
https://nishi-awa.jp/soranosato/

