update content_bodies set title = 'Sora no Sato Nanki-shu Inspection Training', description = 'We went on an inspection training trip to Nanki-shu to enhance the skills of host families for the Sora no Sato Mountain Village Story educational travel and to promote交流 among host families.
We became students ourselves and experienced staying with host families,
considering what would make them happy,
what we could do when we return to our town,
realizing that our own town is the best!!
This became a trigger for various thoughts.
In preparation for hosting starting next spring,
we united once again!!
With high goals set, Sora no Sato Mountain Village Story is moving forward.
Would you like to join us in hosting educational travel?
https://nishi-awa.jp/soranosato/

#Sora no Sato #Sora no Sato Mountain Village Story #Nishi-Awa #Inspection #Training #Learning from Others #Skill Up #Improvement #SDGs #Unity #Tokushima Prefecture #Shikoku #Educational Travel #School Trip #Minpaku #Agricultural Stay #Agriculture, Forestry, and Fisheries Family Inn #Host Families' where id = 'csz1CSmF4XM97HE1sZz5G';
update content_bodies set title = '農泊（ゆずの里いづみ）', description = '徳島県美馬市の農家民宿「ゆずの里いづみ」での体験動画です。
宿からは真正面に標高1,133ｍの高越山が見えます。
また、雨が降れば雲海を見ることができます。
自家製のゆず味噌がやどの自慢です。
ピザ窯があるので、ピザを作って食べることもできますよ♪
畑で採れたばかりの野菜と一緒に召し上がってみてください。

【農家民宿　ゆずの里いづみ】
https://travel.rakuten.co.jp/HOTEL/173443/173443.html

【そらの郷山里物語】
