update content_bodies set title = 'Farm Stay (Yuzu no Sato Izumi)', description = 'This is an experience video at the farm stay ''Yuzu no Sato Izumi'' in Mima City, Tokushima Prefecture.
From the accommodation, you can see Mount Kōchō, which stands at an elevation of 1,133 meters directly in front of you.
Additionally, if it rains, you can enjoy a sea of clouds.
Our homemade yuzu miso is a pride of the inn.
There is a pizza oven, so you can also make and eat pizza! ♪
Please try it with freshly harvested vegetables from the field.

【Farm Stay Yuzu no Sato Izumi】
https://travel.rakuten.co.jp/HOTEL/173443/173443.html

