update content_bodies set title = '愛知・名古屋テクニカルビジットPR動画（ダイジェスト）', description = '愛知・名古屋MICE推進協議会が作成したプロモーション動画で、訪問者が見学し、業界について学ぶことができる企業を紹介しています。
スタッフのインタビューを交えた実際の視察を通じて、視察先の雰囲気やこの地域ならではのテクニカルビジットの魅力を感じていただけます。
ぜひご覧ください！

* 愛知・名古屋MICE推進協議会は、愛知県、名古屋市、名古屋観光コンベンションビューロー、及び愛知・名古屋のMICE関連のステークホルダーで構成されています。
* この動画に含まれている企業は、2021年3月時点の参加企業です。

愛知県、名古屋市、名古屋観光コンベンションビューロー等で構成する愛知・名古屋ＭＩＣＥ推進協議会では、産業視察の受け入れが可能な企業等の視察の様子及び受入先担当者へのインタビューをまとめたプロモーション動画を作成しました。
視察先を実際に巡っている様子をもとに、視察先の雰囲気や、当地域ならではのテクニカルビジットの魅力をご体感いただける内容となっておりますので、ぜひご覧ください！
※この動画に収録されている企業は、作成（令和3年3月）時点の参画企業です。' where id = 'LhRJmEAZKRGKJv-voi6__';
