update content_bodies set title = 'NISEKO SNOW DOME EXPERIENCE Yotei Taiko Show', description = 'From late December 2024 to late February 2025,
we will hold the large snow igloo dome event "NISEKO SNOW DOME EXPERIENCE."
A large multi-purpose dome made of snow, utilizing the heavy snowfall in the Niseko area, will be created,
and a projection mapping show will be held using the ceiling and wall sections inside the igloo.
Additionally, every Thursday and Saturday at the same venue, we held the Yotei Taiko Show.
The powerful performance of Yotei Taiko, which expresses the seasonal beauty of Mount Yotei and the people aiming for the summit through taiko drumming,
was accompanied by a hands-on experience session with the Yotei Taiko Preservation Society, Koryu.

