This time, we introduce ''Akari-AKARU''!

The restaurant is very particular about its ingredients, such as using additive-free, pesticide-free yuzu and pickling wild garlic harvested in spring until winter.

They only operate in winter to prepare ingredients over the course of a year!
Be sure to visit before winter ends!

