update content_bodies set title = '【絶景】北海道ニセコの春。芝桜が美しすぎる！＜Vlog風＞異日常で日常を過ごす滞在型旅行｜ニセコサマーステイ（倶知安観光協会）', description = '北海道ニセコでのサマーステイをオススメするチャンネルです！
このチャンネルは、北海道ニセコエリアにある倶知安観光協会（くっちゃんかんこうきょうかい）が運営しています。 

現在の情勢的にみると、観光に出られる状況ではありませんが、 いつかコロナウィルスが終息し「旅行に出るぞ！」というタイミングに 「北海道ニセコ」が１つの選択肢に上がっていただければ嬉しいなと思っております。
＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝

今回の動画では、ほんと～にオススメの絶景スポットをご紹介してます。
今年はコロナウィルスの影響で見頃の時期にご紹介できなかったのですが、5月下旬~6月上旬にオススメの芝桜です。
ぜひ来年来てみてくださいね！

■三島さんちの芝桜庭園
https://www.town.kutchan.hokkaido.jp/tourism/midokoro/shibazakura/mishimasan/

