update content_bodies set title = '[Spectacular View] Spring in Niseko, Hokkaido. The Shibazakura is too beautiful! <Vlog Style> A stay-type trip to experience an extraordinary daily life | Niseko Summer Stay (Kutchan Tourism Association)', description = 'This is a channel recommending summer stays in Niseko, Hokkaido! 
This channel is operated by the Kutchan Tourism Association located in the Niseko area of Hokkaido.

Given the current situation, it is not possible to travel for tourism, but I hope that when the coronavirus pandemic is over and the time comes to say, ''Let''s travel!'', ''Niseko, Hokkaido'' will be one of the options.
＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝

In this video, I will introduce truly recommended scenic spots. 
This year, due to the impact of the coronavirus, I couldn''t introduce it during the peak season, but I recommend the Shibazakura from late May to early June. 
Please come and visit next year!

■ Mishima''s Shibazakura Garden
https://www.town.kutchan.hokkaido.jp/tourism/midokoro/shibazakura/mishimasan/

*Since this is a private residence, I cannot provide the address. 
I hope you can remember that it is about a 15-20 minute walk from JR Kutchan Station!

*By the way... 
This filming was done at the end of May. 
Last year, it was in full bloom around June 3, but this year it was a bit earlier.

*I apologize for the shaky images!

＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝
The Niseko area in Hokkaido is famous for winter, but summer is also highly recommended! 
I created this channel to convey the ''charm of summer in Niseko''! 
This is just an introductory video, but I plan to upload more videos, so I would be happy if you could subscribe to the channel.

○ General Incorporated Association Kutchan Tourism Association
https://www.niseko.co.jp/

○ Opening & Ending Video
Aaron Jamieson Photography
http://aaronjamieson.com/

