update content_bodies set title = '2025 Forest Kyoto Cultural Tourism Supporter Radio Episode 2: "Washi & Tango Futamata Paper Preservation Society"', description = 'This is the broadcast audio of the radio program "Forest Kyoto presents Do You Know? Traditional Culture in Fukuchiyama" on Kyoto FM Tanba. Two years have passed since the previous series "Do You Know? Traditional Culture in Fukuchiyama". In this series, we welcome our regular guest, Cahal, who is from Ireland and lives in Fukuchiyama, to discuss the intangible cultural assets and traditional culture of Fukuchiyama.

Episode 2: "Washi & Tango Futamata Paper Preservation Society"
In the first half, we introduce the history of paper and the differences between Western paper and washi (Japanese paper).
In the second half, we invite Ms. Yoshiko Omori, the daughter of Mr. Toshihiro Tanaka, the fifth generation of Tanaka Paper Industry, which is the only inheritor of Tango washi, as our guest. She shares her motivations for aspiring to become a washi craftsman, her current feelings, and talks about the activities of the Tango Futamata Paper Preservation Society.

