Cahal O''Callaghan: Originally from Ireland, now in his second year living in Fukuchiyama, teaching English to children. Very interested in Japanese traditional culture and performing arts. A kind-hearted sportsman. Currently studying Japanese intensively.' where id = 'ZUE2-ZdflD9GP1U06-ksu';
update content_bodies set title = '【長野県 木曽路観光】塩尻市の人気スポット、奈良井宿をご紹介 Best spots to visit & photogenic places around Narai-juku', description = '撮影スポット詳細ページ「木曽谷とりっぷ」→　https://kiso-nagano.ne.jp/youtubespot-shiojiri/

【塩尻市】中山道の真ん中に位置する大人気の宿場町「奈良井宿」。今でも残る200年前の街並みを散策すると、まるでタイムスリップしたかのような気分。約１㎞の宿場町には築180年の古民家カフェなど、味だけでなく雰囲気も楽しむことのできるカフェやレストランが集まっています。また木曽漆器などの伝統工芸店が軒を連ねております。一度は訪れたい人気の観光名所！

【紹介場所】
♦木曽くらしの工芸館
→https://www.kiso.or.jp/
♦贄川関所
→https://www.city.shiojiri.lg.jp/soshiki/75/3813.html

