update content_bodies set title = 'Best spots to visit & photogenic places around Narai-juku', description = 'Details of the shooting spot page "Kiso Valley Trip" → https://kiso-nagano.ne.jp/youtubespot-shiojiri/

[Narai-juku, Shiojiri City] A popular post town located in the middle of the Nakasendo. Strolling through the streets that have remained for 200 years gives you a feeling of time slipping away. The approximately 1 km long post town is home to cafes and restaurants where you can enjoy not only the taste but also the atmosphere, including a 180-year-old traditional house café. Additionally, traditional craft shops such as Kiso lacquerware line the streets. A popular tourist destination that you must visit at least once!

[Featured Locations]
♦ Kiso Living Craft Museum
→ https://www.kiso.or.jp/
♦ Niegawa Checkpoint
→ https://www.city.shiojiri.lg.jp/soshiki/75/3813.html

